int main(int argc,char**argv)try{
 if(argc!=5)return 2;auto scene=Scene::load(argv[1]);auto&id=scene.object(std::stoull(argv[2]));const uint32_t wanted=uint32_t(std::stoul(argv[3]));auto&m=id.painted->mesh();auto&rig=*id.deformation->skeleton;using P=detail::bone_shadow::Point;std::vector<uint32_t>parents(m.positions.size());std::iota(parents.begin(),parents.end(),0);auto root=[&](uint32_t x){while(parents[x]!=x){parents[x]=parents[parents[x]];x=parents[x];}return x;};for(size_t t=0;t<m.indices.size();t+=3)for(size_t k=0;k<3;++k){auto a=root(m.indices[t+k]),b=root(m.indices[t+(k+1)%3]);if(a!=b)parents[std::max(a,b)]=std::min(a,b);}for(auto&x:parents)x=root(x);if(wanted>=parents.size()||parents[wanted]!=wanted)throw std::runtime_error("Actual captured component root required");std::vector<P>points;for(auto p:m.positions)points.push_back({p.x,p.y,p.z});std::vector<uint32_t>rows,local;std::map<std::array<uint32_t,2>,std::pair<size_t,int>>edges;std::map<P,std::vector<uint32_t>>positions;for(uint32_t i=0;i<points.size();++i){positions[points[i]].push_back(i);if(parents[i]==wanted)rows.push_back(i);}for(size_t t=0;t<m.indices.size();t+=3)if(parents[m.indices[t]]==wanted){for(size_t k=0;k<3;++k){local.push_back(m.indices[t+k]);auto a=m.indices[t+k],b=m.indices[t+(k+1)%3];auto&edge=edges[{std::min(a,b),std::max(a,b)}];++edge.first;edge.second+=a<b?1:-1;}}
 size_t boundary=0,nonmanifold=0,inconsistent=0,duplicates=0;for(auto&[e,data]:edges){boundary+=data.first==1;nonmanifold+=data.first>2;inconsistent+=data.first==2&&data.second!=0;}for(auto v:rows)for(auto other:positions[points[v]])duplicates+=parents[other]!=wanted;
 std::function<bool()>cancel;detail::weight_surface::Budget work{0,500'000'000,cancel};using Q=detail::visibility_geodesic::ClosestRayVisibility;Q full(points,m.indices,128u*1024u*1024u,work),part(points,local,128u*1024u*1024u,work);Q::Scratch full_s(full),part_s(part);auto segments=rig.segments();nlohmann::json bones=nlohmann::json::array();size_t full_visible=0,local_visible=0;
 for(uint32_t b=0;b<rig.bones.size();++b)if(rig.bones[b].deform){P a{segments[b][0].x,segments[b][0].y,segments[b][0].z},z{segments[b][1].x,segments[b][1].y,segments[b][1].z};size_t yes=0,own=0,candidates=0;float nearest=INFINITY;for(auto v:rows){float d=detail::visibility_geodesic::distance(points[v],a,z);nearest=std::min(nearest,d);if(d>.3f)continue;++candidates;yes+=full.visible(v,a,z,full_s,work);own+=part.visible(v,a,z,part_s,work);}full_visible+=yes;local_visible+=own;bones.push_back({{"joint",b},{"label_diagnostic_only",rig.bones[b].name},{"closest_m",nearest},{"candidates",candidates},{"whole_mesh_visible",yes},{"same_component_visible",own}});}
 nlohmann::json report{{"object",id.id},{"name",id.name},{"component",wanted},{"vertices",rows},{"triangles",local.size()/3},{"boundary_edges",boundary},{"nonmanifold_edges",nonmanifold},{"inconsistent_edges",inconsistent},{"duplicate_positions_in_other_components",duplicates},{"whole_mesh_visible",full_visible},{"same_component_visible",local_visible},{"work",work.used},{"bones",bones},{"policy","read-only prospective wall-domain control, not a failed-field retry or production bypass"}};std::ofstream(argv[4])<<report.dump(2);std::cout<<report.dump(2)<<std::endl;return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}
